// CabinetOS Game events: each person's games go to their own Discord channel.
// One line per person: the name exactly as the console shows it, then that
// person's Discord webhook (in Discord: Edit Channel, Integrations, Webhooks).
// Anyone not listed goes nowhere, and so does the console's test message.
const PEOPLE = {
  "First person": "https://discord.com/api/webhooks/PASTE-THEIR-WEBHOOK",
  "Second person": "https://discord.com/api/webhooks/PASTE-THEIR-WEBHOOK",
};
// The messages to send. Delete the ones you do not want: with only
// "game_started" left, only game starts are posted.
const SEND = ["game_started", "game_paused", "game_resumed", "game_ended", "achievement_unlocked", "set_completed"];

const CYAN = 0x58E8F6, PURPLE = 0xA07CF0, GOLD = 0xF2C14E;
const COVER = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp' };

function minutes(n) {
  if (!n) return 'less than a minute';
  return n === 1 ? '1 minute' : `${n} minutes`;
}

const out = [];
for (const item of $input.all()) {
  const m = item.json.body ?? {};
  const url = PEOPLE[m.person];
  if (!url || !SEND.includes(m.event)) continue;
  const linkup = m.linkup_game === 'hosting' || m.linkup_game === 'joined';
  const over = linkup ? ' over LinkUp' : '';
  const who = `**${m.person}**`, game = `**${m.game}**`;
  const points = m.points === 1 ? '1 point' : `${m.points} points`;

  // Started and every achievement: a card, with the cover when it came.
  let card = null;
  if (m.event === 'game_started') {
    card = { author: m.linkup_game === 'joined' ? `🎮 ${m.person} joined a LinkUp game`
                                                 : `🎮 ${m.person} started playing${over}`,
             color: linkup ? PURPLE : CYAN };
  } else if (m.event === 'set_completed') {
    card = { author: `🌟 ${m.person} unlocked every achievement${over}`, color: GOLD };
  }
  // The rest: one line each.
  const line = {
    game_paused: `⏸️ ${who} paused ${game}${over}`,
    game_resumed: `▶️ ${who} is back in ${game}${over}`,
    game_ended: `🛑 ${who} stopped playing ${game}${over} after ${minutes(m.minutes_played)}`,
    achievement_unlocked: `🏆 ${who} unlocked **${m.achievement}** (${points}) in ${game}${over}`,
  }[m.event];
  if (!card && !line) continue;

  const post = { json: { url, cover: false, payload: { allowed_mentions: { parse: [] } } } };
  if (line) post.json.payload.content = line;
  if (card) {
    const embed = { author: { name: card.author }, title: m.game, color: card.color };
    if (m.system) embed.description = m.system;
    const type = COVER[m.cover_type];
    if (m.cover && type) {
      const file = `cover.${type}`;
      embed.thumbnail = { url: `attachment://${file}` };
      post.json.cover = true;
      post.binary = { cover: { data: m.cover, mimeType: m.cover_type, fileName: file } };
    }
    post.json.payload.embeds = [embed];
  }
  out.push(post);
}
return out;
